css:
.slide[data-slide="opening"] .hero { display:grid; place-items:center; gap:var(--space-3); height:100%; }
.slide[data-slide="opening"] .count { font: 800 clamp(180px, 22vw, 380px)/1 var(--font); color: var(--accent); }
.slide[data-slide="opening"] .cap { font: 500 var(--type-subtitle) var(--font); color: var(--fg-muted); }
